#!/usr/bin/env bash
# ck-code SessionStart hook.
#   (1) Reload skills so experts/guides generated by /ck-code:team become
#       invocable in the same session — no restart required.
#   (2) Compare the project's layout stamp with this plugin: an older layout gets a
#       migrate notice, a newer one (or a `requires:` above this version) gets an
#       update-the-plugin notice. Never the reverse.
#   (3) Regenerate the views. They are not committed, so a fresh clone, a checkout or
#       a pull leaves them missing or behind the frontmatter they project.
#   (4) Inject a one-line workflow summary aggregated across every plan's view.
#   (5) Keep the committed ".claude/ck-code-required.sh" guard current, so a clone
#       of this repo on a machine with no ck-code is told to install it first.
#
# Writes nothing tracked by git: the stamp is never rewritten here, and the views sit
# behind tasks/.gitignore. A session start never leaves the tree dirty.
#
# Best-effort by design: this must NEVER fail or block session startup, so it
# avoids `set -e` and swallows every probe error. Output is a single JSON line.
# JSON is assembled with a proper string escape (no raw interpolation) so a path
# containing a quote or backslash cannot produce invalid JSON.

CK_HERE="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)"
# shellcheck source=scripts/lib/ck-common.sh
. "$CK_HERE/lib/ck-common.sh"

json_escape() { ck_json_escape "$1"; }

emit() { # emit CONTEXT_STRING
  local esc; esc=$(json_escape "$1")
  printf '{"hookSpecificOutput":{"hookEventName":"SessionStart","reloadSkills":true,"additionalContext":"%s"}}\n' "$esc"
}
emit_plain() {
  printf '{"hookSpecificOutput":{"hookEventName":"SessionStart","reloadSkills":true}}\n'
}

# ---- ck-code-required guard --------------------------------------------------
# A ck-code project keeps its state in a layout only the plugin maintains, so a clone on
# a machine that never installed ck-code has no /ck-code:* command and nothing in the
# plugin able to say so -- the plugin is what is missing. The guarantee therefore lives
# in the repo: .claude/ck-code-required.sh, committed, wired as the project's own
# SessionStart hook by ck-bootstrap.
#
# Installed from here rather than left to the user because it is the one write that
# cannot wait for "the next time you run a skill": a project stamped before this release
# short-circuits the version gate at Tier 1 and never reaches its stamp step again.
# Purely local, idempotent, and announced -- never silent.
#
# Computed before the tasks/ check: the leftover-vendor warning applies to a project with
# no plan yet.
CK_NOTE=""
guard_notice() {
  local sh want have
  sh="$CK_HERE/ck-bootstrap.sh"
  [ -x "$sh" ] || return 0

  # Only a stamped project gets the guard -- the guard's own trigger is tasks/VERSION.md,
  # so installing it anywhere else would commit a permanent no-op.
  if [ -f tasks/VERSION.md ]; then
    want="$CK_GUARD_VERSION"
    have=$(awk '/^# ck-code-guard:/{print $3; exit}' .claude/ck-code-required.sh 2>/dev/null)
    if [ -n "$want" ] && [ "$have" != "$want" ]; then
      if "$sh" install >/dev/null 2>&1; then
        CK_NOTE="ck-code wrote .claude/ck-code-required.sh and a SessionStart entry in .claude/settings.json, so a clone of this repo on a machine without ck-code is told to install it first -- commit both."
      fi
    fi
  fi

  # Vendoring was removed in 6.11.0. A copy left behind by it still loads as
  # ck-code@skills-dir, a *different* plugin id from ck-code@ck-marketplace -- neither
  # shadows the other, so both run and every /ck-code:* command is listed twice, one of
  # them frozen at whatever version was vendored. Reported only: the tree is committed
  # project content, and deleting it is the user's call.
  if [ -f .claude/skills/ck-code/.claude-plugin/plugin.json ]; then
    CK_NOTE="${CK_NOTE:+$CK_NOTE }This project still carries a vendored copy of ck-code at .claude/skills/ck-code/. Vendoring was removed in 6.11.0; while that folder is present every /ck-code:* command is listed twice and one copy never updates. Delete the folder, remove the ck-code@skills-dir key from .claude/settings.json, then run /plugin install ck-code@ck-marketplace."
  fi
}
guard_notice

# ---- pending Claude Design link ---------------------------------------------
# /ck-code:spec can hand the user a design brief to build at claude.ai/design and then
# stop -- the user may come back days later, in a session that never saw that
# conversation. The only thing bridging the gap is docs/specs/*/.metadata.json, so the
# reminder is re-derived here from disk.
#
# Deliberately BEFORE the `tasks/` early-exit below: a project that has only ever run
# `spec` has no tasks/ directory at all, and that is exactly the project waiting.
# Suppressed once the cache exists -- a linked project has nothing to be reminded of.
ds_pending_notice() {
  [ -d docs/specs ] || return 0
  [ -d docs/architecture/design-system ] && return 0
  local hits n first
  hits=$(grep -l '"awaiting-link"' docs/specs/*/.metadata.json 2>/dev/null)
  [ -n "$hits" ] || return 0
  n=$(printf '%s\n' "$hits" | grep -c .)
  first=$(printf '%s\n' "$hits" | head -1)
  first=$(dirname "$first")
  local what="a Claude Design system is pending for $first"
  [ "$n" -gt 1 ] && what="a Claude Design system is pending for $n specs (including $first)"
  CK_NOTE="${CK_NOTE:+$CK_NOTE }ck-code: $what. Once the design system is ready at claude.ai/design, paste its URL into /ck-code:design ds <url> to link and cache it."
}
ds_pending_notice

# No tasks/ at all → nothing to summarise (the guard notice may still be worth saying).
[ -d tasks ] || { if [ -n "$CK_NOTE" ]; then emit "$CK_NOTE"; else emit_plain; fi; exit 0; }

# Layout check. LAYOUT must track references/version-gate.md (tests/smoke.sh asserts
# it) — a stale value here nags every correctly-stamped project on every start.
LAYOUT=v7
layout="$(ck_stamp layout)"
has_plan=$(ls -d tasks/*/epics 2>/dev/null | head -1)
running="$(ck_plugin_version)"
required="$(ck_stamp requires)"

want_n=${LAYOUT#v}
have_n=${layout#v}
case "$have_n" in ""|*[!0-9]*) have_n="" ;; esac

if [ -n "$have_n" ] && [ "$have_n" -gt "$want_n" ]; then
  emit "This project uses ck-code layout $layout, newer than this ck-code ($running, layout $LAYOUT). Update the plugin before using any /ck-code:* command: /plugin update ck-code@ck-marketplace, then restart. Never run /ck-code:migrate here — it cannot convert a newer layout down.${CK_NOTE:+ $CK_NOTE}"
  exit 0
fi
if [ -n "$required" ] && [ -n "$running" ] && ck_version_lt "$running" "$required"; then
  emit "This project requires ck-code >= $required and this session runs $running. Update the plugin before using any /ck-code:* command: /plugin update ck-code@ck-marketplace, then restart.${CK_NOTE:+ $CK_NOTE}"
  exit 0
fi
if [ -n "$has_plan" ] && [ "$layout" != "$LAYOUT" ]; then
  emit "ck-code detected a ${layout:-pre-$LAYOUT} project layout; this ck-code uses $LAYOUT. Run /ck-code:migrate to upgrade it (one-shot, safe, one revertable commit) before using design/plan/build/fix.${CK_NOTE:+ $CK_NOTE}"
  exit 0
fi

# Views: regenerated here, from frontmatter, whenever any is missing or stale. The
# stamp-less, plan-less project (only a design so far) has nothing to project.
if [ -n "$has_plan" ] && ! ck_views_fresh; then
  ck_run ck-index >/dev/null 2>&1 || true
fi

# Current-layout project: aggregate story counts across ALL plans (Status is the 5th
# |-field, Delivery the 6th). ck-index.sh escapes a literal pipe in a title as `\|`;
# splitting on a bare `|` would count that as a column and read the wrong field, so
# neutralise it first.
#
# The Delivery tally is the merge probe. A row reading `PR #<n>` has an anchor GitHub
# may already have merged, and nothing in ck-code observes a merge as it happens — so
# the count is surfaced here and reconciled by `ck-project sync`. This stays a LOCAL
# read of a generated file: a hook that called the network would delay every session
# start and fail on an unauthenticated machine.
counts=$(awk '
  FNR==1{next}
  {
    line=$0; gsub(/\\\|/,"\001",line)
    n=split(line,f,"|")
    if (n>=7) {
      s=f[5]; gsub(/^[ \t]+|[ \t]+$/,"",s)
      if(s=="TODO")todo++; else if(s=="IN PROGRESS")ip++; else if(s=="DONE")done++; else if(s=="BUG")bug++
      d=f[6]; gsub(/^[ \t]+|[ \t]+$/,"",d)
      if(d ~ /^PR/) pend++
    }
  }
  END{ printf "%d %d %d %d %d", todo, ip, done, bug, pend }
' tasks/*/STORIES_INDEX.md 2>/dev/null)

if [ -n "$counts" ]; then
  set -- $counts
  todo=${1:-0}; ip=${2:-0}; done=${3:-0}; bug=${4:-0}; pend=${5:-0}
  # All-zero means the indexes carry no story rows — say nothing rather than
  # emit a vacuous "0 TODO, 0 IN PROGRESS, 0 DONE".
  if [ $((todo + ip + done + bug)) -eq 0 ]; then
    if [ -n "$CK_NOTE" ]; then emit "$CK_NOTE"; else emit_plain; fi
    exit 0
  fi
  msg="ck-code project: $todo TODO, $ip IN PROGRESS, $done DONE"
  [ "${bug:-0}" -gt 0 ] && msg="$msg, $bug BUG"
  msg="$msg. Run /ck-code:track for the next step."
  [ "${pend:-0}" -gt 0 ] && msg="$msg $pend awaiting merge confirmation — /ck-code:doctor --fix reconciles them, and /ck-code:ship does it first."
  [ -n "$CK_NOTE" ] && msg="$msg $CK_NOTE"
  emit "$msg"
elif [ -n "$CK_NOTE" ]; then
  emit "$CK_NOTE"
else
  emit_plain
fi
